/// <summary>
/// Extension to CustTable to display order count for each customer.
/// </summary>
[ExtensionOf(tableStr(CustTable))]
final class SOrderCustTable_Extension
{
}

Method.Source:
/// <summary>
/// Displays the count of orders for the current customer.
/// </summary>
/// <returns>The number of orders for this customer.</returns>
public display int sOrderCount()
{
    SOrderTable orderTable;
    select count(RecId) from orderTable
        where orderTable.CustAccount == this.AccountNum;
    return any2Int(orderTable.RecId);
}
